<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Infrastructure\Driver\Rest;

use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use OpenApi\Attributes as OA;
use Throwable;
use DateTime;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Retrieve\UserFederatedIdentityRetrieveUsecase;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Retrieve\UserFederatedIdentityRetrieveResult;

class UserFederatedIdentityRetrieveController
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly UserFederatedIdentityRetrieveUsecase $retrieveUsecase,
    ) {
    }
    #[OA\Get(
        path: "/api/access/user-federated-identities{uid}",
        tags: ["User federated identity"],
        description:"Create",
        parameters: [
               new OA\PathParameter(name: "uid", required: true, schema: new OA\Schema(type: "string")),
          ],
        responses: [
              new OA\Response(response: 201, description: "Ok", content: new OA\JsonContent(type: "object", ref:"#/components/schemas/UserFederatedIdentityApiDTO")),
              new OA\Response(response: 404, description: "Not found"),
          ]
    )]
    public function retrieve(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $this->logDebug("Retrieve User federated identity");
        $span = $this->startSpan("Retrieve User federated identity");
        try {
            if (!isset($args['uid'])) {
                throw new NotFoundException('-');
            }
            $uid = $args['uid'];
            $result = $this->retrieveUsecase->retrieve($uid);
            $value = $this->mapUserFederatedIdentity($request, $result);
            $encoded = json_encode($value);
            $response->getBody()->write($encoded === false ? '' : $encoded);
            return $response->withStatus(200)
                  ->withHeader('Content-Type', 'application/json');
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    private function mapUserFederatedIdentity(ServerRequestInterface $request, UserFederatedIdentityRetrieveResult $value): UserFederatedIdentityApiDTO
    {
        $this->logDebug("Map entity to output dto for User federated identity");
        $span = $this->startSpan("Map entity to output dto for User federated identity");
        try {
            $user = $value->getUser();
            $loginProvider = $value->getLoginProvider();
            $dto = new UserFederatedIdentityApiDTO();
            $dto->uid = $value->getUid();
            $dto->user = $user ? ['$ref' => $user->uid()] : null;
            $dto->loginProvider = $loginProvider ? ['$ref' => $loginProvider->uid()] : null;
            $dto->subject = $value->getSubject();
            $dto->createdAt = $value->getCreatedAt()?->format(DateTime::ATOM);
            $dto->version = $value->getVersion();
            return $dto;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
